// Start searching from min_bit position
size_t group = min_bit >> LG_BITMAP_GROUP_NBITS;
size_t bit_in_group = min_bit & BITMAP_GROUP_NBITS_MASK;

// Search through groups linearly
for (; group < binfo->levels[0]; group++) {
    bitmap_t g = bitmap[group];
    // If group is not all ones, there's an unset bit
    if (g != ~(bitmap_t)0) {
        // Search within the group
        bitmap_t mask = ~g;
        // If we're starting mid-group, mask out lower bits
        if (group == (min_bit >> LG_BITMAP_GROUP_NBITS)) {
            mask &= ~((bitmap_t)1 << bit_in_group) - 1;
        }
        // Find first set bit in mask (which corresponds to unset bit in original)
        if (mask != 0) {
            size_t bit = ffs_lu(mask) + (group << LG_BITMAP_GROUP_NBITS);
            // Ensure we don't return a bit beyond nbits
            return (bit < binfo->nbits) ? bit : binfo->nbits;
        }
    }
    // Reset bit_in_group for subsequent groups
    bit_in_group = 0;
}

// No unset bit found
return binfo->nbits;

